<?php require_once 'config.php';$pageTitle='Redefinir senha';$msg='';$type='info';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$email=strtolower(trim($_POST['email']??''));if(!valid_email($email)){$msg='Informe um e-mail válido.';$type='danger';}else{$s=db()->prepare('SELECT id FROM usuarios WHERE email=?');$s->execute([$email]);$uid=$s->fetchColumn();if($uid){$token=bin2hex(random_bytes(32));$hash=hash('sha256',$token);$s=db()->prepare('INSERT INTO solicitacoes_redefinicao(usuario_id,email,token_hash,expira_em) VALUES(?,?,?,DATE_ADD(NOW(), INTERVAL 30 MINUTE))');$s->execute([$uid,$email,$hash]);$msg='Solicitação de redefinição registrada.';$type='success';}else{$msg='E-mail não encontrado.';$type='danger';}}}require 'includes/header.php'; ?><div class="form-wrap"><form class="form-card" method="post"><h1>Esqueceu sua senha?</h1><p>Informe o e-mail associado à sua conta para registrar a solicitação de redefinição.</p><?php if($msg): ?><div class="alert <?= e($type) ?>"><?= e($msg) ?></div><?php endif; ?><input type="hidden" name="csrf" value="<?= csrf() ?>"><div class="field"><label>E-mail cadastrado</label><input type="email" name="email" required></div><button class="btn">SOLICITAR REDEFINIÇÃO</button><div class="form-foot"><a href="login.php">Voltar ao login</a></div><p class="notice">O registro da solicitação está implementado. O envio de e-mail e a página de validação do token dependem da configuração de um serviço de e-mail; nenhuma senha é alterada nesta etapa.</p></form></div><?php require 'includes/footer.php'; ?>
